def borrowDist (s : St) (who : Account) : Option St :=
  if s.borrowState.block ≤ s.blockNumber then
    let bd := accrueSide s.borrowState s.blockNumber (totalBorrows s)
    let bt := accrualStart (s.acct who).borrowerIndex bd.index
    if bt ≤ bd.index then
      some { s with borrowState := bd, accts := s.accts.modify who fun a => { a with borrowerIndex := bd.index, accrued := a.accrued + creditFor a.borrow bt bd.index } }
    else none
  else none

